// Trophy registry — single source of truth for the achievement system.
//
// Image assets live in public/trophies/<id>.png and are generated by
// scripts/generate-trophies.ts. Keep the id list here in sync with the
// TROPHIES array in that script — the generated png filenames must
// match the id field exactly.
//
// Each trophy has a "kind":
//   - "stack": every time the milestone fires, the count increments and
//     an earned-modal pops with "Now ×N". Used for repeatable wins
//     (spell a particular word; finish A→Z in a particular case;
//     match a sound).
//   - "milestone": one-shot achievement. Earned modal shows once, count
//     stays at 1 forever (unless trophies are reset). Used for tier-up
//     style rewards like "spelled 25 words total".
//
// The shelf renders trophies in this declared order, so think of this
// as the on-screen layout from top-left to bottom-right.

export type TrophyId =
  | "alphabet-upper"
  | "alphabet-lower"
  | "alphabet-mixed"
  | "spell-cat"
  | "spell-dog"
  | "spell-sun"
  | "spell-bus"
  | "spell-pig"
  | "spell-tree"
  | "spell-star"
  | "spell-book"
  | "spell-ball"
  | "spell-cake"
  | "spell-hen"
  | "sound-match"
  | "word-wizard";

export type TrophyKind = "stack" | "milestone";

export type TrophySpec = {
  id: TrophyId;
  // Short display name (spoken aloud on tap, shown small under the tile).
  name: string;
  // Tile background colour on the shelf — picked to make the trophy art pop.
  tileColor: string;
  // What the kid did to earn it. One short sentence; surfaces in the
  // earn modal under the trophy and on the shelf as accessibility text.
  trigger: string;
  // Stack vs one-shot.
  kind: TrophyKind;
  // Emoji fallback used when the PNG is missing (e.g. asset gen failed,
  // running before scripts/generate-trophies.ts has been run).
  fallbackEmoji: string;
};

