const BY_ID: Record<TrophyId, TrophySpec> = TROPHIES.reduce(
  (acc, t) => {
    acc[t.id] = t;
    return acc;
  },
  {} as Record<TrophyId, TrophySpec>,
);

export function getTrophy(id: TrophyId): TrophySpec {
  return BY_ID[id];
}

export const ALL_TROPHY_IDS: TrophyId[] = TROPHIES.map((t) => t.id);

// Total spell-the-word completions needed for the Word Wizard milestone.
// Lives here so games and the trophy lab share one constant.
export const WORD_WIZARD_THRESHOLD = 25;

// How many times the kid must spell the SAME word before earning that
// word's trophy (and then again before stacking +1). Tuned so each
// trophy feels like a real achievement instead of an instant reward
// after a single play.
export const SPELL_REPS_PER_TROPHY = 5;

// All per-word spell trophies. Word Wizard fires when the SUM of all
// per-word completion counts reaches WORD_WIZARD_THRESHOLD — that's
// "spelled 25 words across any combination."
